{"command":"cat > src/uri.js <<'EOF'
const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {}

export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

export function splitAuthority(a) {
  let userinfo
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const rb = a.lastIndexOf(']')
  const colon = a.indexOf(':', rb + 1)
  let host = a, port
  if (colon >= 0) { host = a.slice(0, colon); port = a.slice(colon + 1) }
  return { userinfo, host, port }
}

export function removeDots(path) {
  let inp = path
  const out = []
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../')) { inp = inp.slice(3); out.pop() }
    else if (inp === '/..') { inp = '/'; out.pop() }
    else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', inp.startsWith('/') ? 1 : 0)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out.push(seg)
      inp = inp.slice(seg.length)
    }
  }
  return out.join('')
}

const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function pct(s) {
  return s.replace(/%([0-9a-fA-F]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

function checkPct(s) {
  return !/%(?![0-9a-fA-F]{2})/.test(s)
}

export function check(c, line) {
  const parts = [['path', c.path]]
  if (c.authority !== undefined) {
    const a = splitAuthority(c.authority)
    parts.push(['userinfo', a.userinfo], ['host', a.host])
  }
  parts.push(['query', c.query], ['fragment', c.fragment])
  for (const [name, v] of parts) {
    if (v !== undefined && !checkPct(v)) {
      throw new UriError(`line ${line}: the ${name} has a truncated percent-encoding`)
    }
  }
}

export function normalize(c) {
  const scheme = c.scheme === undefined ? undefined : lower(c.scheme)
  let authority
  if (c.authority !== undefined) {
    const a = splitAuthority(c.authority)
    authority = ''
    if (a.userinfo !== undefined) authority += pct(a.userinfo) + '@'
    authority += lower(pct(a.host))
    if (a.port !== undefined) {
      const p = pct(a.port)
      if (p !== '' && !(scheme !== undefined && DEFAULT_PORTS[scheme] === p)) authority += ':' + p
    }
  }
  let path = removeDots(pct(c.path))
  if (authority !== undefined && path === '') path = '/'
  return unparse({
    scheme, authority, path,
    query: c.query === undefined ? undefined : pct(c.query),
    fragment: c.fragment === undefined ? undefined : pct(c.fragment),
  })
}

export function unparse(c) {
  let r = ''
  if (c.scheme !== undefined) r += c.scheme + ':'
  if (c.authority !== undefined) r += '//' + c.authority
  r += c.path
  if (c.query !== undefined) r += '?' + c.query
  if (c.fragment !== undefined) r += '#' + c.fragment
  return r
}

export function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  if (ref.authority !== undefined) return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, authority: base.authority, fragment: ref.fragment }
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let merged
      if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
      }
      t.path = removeDots(merged)
    }
    t.query = ref.query
  }
  return t
}
