cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'
import { parse, normalize, resolve, check, unparse, UriError } from './uri.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const out = []
try {
  lines.forEach((rec, idx) => {
    const n = idx + 1
    if (mode === 'normalize') {
      const c = parse(rec)
      check(c, n)
      out.push(normalize(c))
      return
    }
    const sp = rec.indexOf(' ')
    if (sp < 0) throw new UriError(`line ${n}: expected a base and a reference`)
    const base = parse(rec.slice(0, sp))
    if (base.scheme === undefined) throw new UriError(`line ${n}: the base has no scheme`)
    const t = resolve(base, parse(rec.slice(sp + 1)))
    check(t, n)
    out.push(normalize(t))
  })
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
