      if (ch === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        j = i + 2
        const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        if (!run(pred)) bad = true
