{"file_path":"src/parser.js","content":"const newTable = () => ({ t: 'table', m: new Map(), hdr: false })
const join = (p, k) => (p === '' ? k : `${p}.${k}`)

class Fail extends Error {
  constructor(reason) {
    super(reason)
    this.reason = reason
  }
}
const fail = (r) => {
  throw new Fail(r)
}

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/
const BARE = /[A-Za-z0-9_-]/
const HEX4 = /^[0-9a-fA-F]{4}$/

/** Step into `name` of `table` for walking; creates a table when absent. */
function step(table, name, path) {
  let n = table.m.get(name)
  if (n === undefined) {
    n = newTable()
    table.m.set(name, n)
    return n
  }
  if (n.t === 'table') return n
  if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
  return fail(`${path} is not a table`)
}

function assign(table, basePath, names, node) {
  let path = basePath
  for (let k = 0; k < names.length - 1; k++) {
    path = join(path, names[k])
    table = step(table, names[k], path)
  }
  const last = names[names.length - 1]
  path = join(path, last)
  if (table.m.has(last)) fail(`key ${path} is defined twice`)
  table.m.set(last, node)
}

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++
  }
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  name() {
    this.ws()
    const c = this.s[this.i]
    if (c === '"') {
      this.i++
      return this.basic()
    }
    if (c === "'") {
      this.i++
      return this.literal()
    }
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }
  basic() {
    const s = this.s
    let out = ''
    for (;;) {
      if (this.i >= s.length) fail('unterminated string')
      const c = s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c !== '\\') {
        out += c
        this.i++
        continue
      }
      if (this.i + 1 >= s.length) fail('unterminated string')
      const e = s[this.i + 1]
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(simple, e)) {
        out += simple[e]
        this.i += 2
      } else if (e === 'u') {
        const h = s.slice(this.i + 2, this.i + 6)
        if (!HEX4.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 6
      } else {
        fail(`invalid escape \\${String.fromCodePoint(s.codePointAt(this.i + 1))}`)
      }
    }
  }
  literal() {
    const end = this.s.indexOf("'", this.i)
    if (end < 0) fail('unterminated string')
    const v = this.s.slice(this.i, end)
    this.i = end + 1
    return v
  }
  value(path) {
    this.ws()
    if (this.atEnd()) fail('expected a value')
    const s = this.s
    const c = s[this.i]
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') {
      this.i++
      return { t: 'string', v: this.basic() }
    }
    if (c === "'") {
      this.i++
      return { t: 'string', v: this.literal() }
    }
    if (c === '[') {
      this.i++
      return this.array(path)
    }
    if (c === '{') {
      this.i++
      return this.inline(path)
    }
    const st = this.i
    while (this.i < s.length && !' \t,]};'.includes(s[this.i])) this.i++
    const w = s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    return fail(`invalid value ${w}`)
  }
  array(path) {
    const node = { t: 'array', items: [], aot: false }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return node
      }
      node.items.push(this.value(`${path}[${node.items.length}]`))
      this.ws()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === ']') {
        this.i++
        return node
      } else fail('unterminated array')
    }
  }
  inline(path) {
    const node = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.s[this.i] === '}') {
      this.i++
      return node
    }
    for (;;) {
      const names = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      let p = path
      for (const n of names) p = join(p, n)
      const v = this.value(p)
      assign(node, path, names, v)
      this.ws()
      const c = this.s[this.i]
      if (c === ',') {
        this.i++
        continue
      }
      if (c === '}') {
        this.i++
        return node
      }
      fail('unterminated inline table')
    }
  }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = ''
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const line = lines[ln]
      const p = new LineParser(line)
      p.ws()
      if (p.atEnd()) continue
