{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let cands = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const word = t[0]
    if (word === 'candidates') {
      if (cands !== null || ballots.length) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      cands = t.slice(1)
    } else if (word === 'ballot') {
      if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (cands === null) fail('error: no candidates')
  return { cands, ballots }
}

function run(cands, ballots) {
  const alive = new Set(cands)
  const history = []
  const out = []
  let winner = null
  for (let k = 1; ; k++) {
    const counts = new Map([...alive].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((p) => alive.has(p))
      if (c !== undefined) {
        counts.set(c, counts.get(c) + b.count)
        active += b.count
      }
    }
    history.push(counts)
    const list = [...counts.entries()].sort((a, b) => (a[1] === b[1] ? (a[0] < b[0] ? -1 : 1) : a[1] > b[1] ? -1 : 1))
    let line = `round ${k}: ` + list.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
    out.push(line)
    if (active === 0n) break
    const w = list.find(([, v]) => v * 2n > active)
    if (w) {
      winner = w[0]
      break
    }
    let min = list.reduce((m, [, v]) => (v < m ? v : m), list[0][1])
    let tied = list.filter(([, v]) => v === min).map(([c]) => c)
    outer: while (tied.length > 1) {
      for (const h of history) {
        const vals = tied.map((c) => h.get(c))
        const lo = vals.reduce((m, v) => (v < m ? v : m))
        if (vals.some((v) => v !== lo)) {
          tied = tied.filter((c) => h.get(c) === lo)
          continue outer
        }
      }
      break
    }
    tied.sort()
    const el = tied[tied.length - 1]
    alive.delete(el)
    out.push(`eliminated ${el}`)
  }
  return { out, rounds: history.length, winner }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
const { cands, ballots } = parse(readFileSync(0, 'utf8'))
const r = run(cands, ballots)
const end = r.winner ? `winner ${r.winner}` : 'no winner'
const lines = args[0] === 'rounds' ? [...r.out, end] : [`rounds ${r.rounds}`, end]
process.stdout.write(lines.join('\n') + '\n')
EOF
