{"file_path":"src/parse.js","content":"/** Parses election text into { candidates, ballots }; throws parse errors with isParseError. */
function err(message) {
  const e = new Error(message)
  e.isParseError = true
  return e
}

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  let known = null
  let ballotSeen = false
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    const word = t[0]
    if (word === 'candidates') {
      if (candidates !== null || ballotSeen) throw err(`error: line ${n}: candidates must be declared once, before any ballot`)
      if (t.length < 2) throw err(`error: line ${n}: expected candidates <name>...`)
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) throw err(`error: line ${n}: invalid candidate name ${name}`)
        if (seen.has(name)) throw err(`error: line ${n}: candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
      known = seen
    } else if (word === 'ballot') {
      if (candidates === null) throw err(`error: line ${n}: candidates must be declared once, before any ballot`)
      ballotSeen = true
      if (t.length < 3) throw err(`error: line ${n}: expected ballot <count> <candidate>...`)
      if (!/^[1-9][0-9]*$/.test(t[1])) throw err(`error: line ${n}: count must be a positive integer`)
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!known.has(name)) throw err(`error: line ${n}: unknown candidate ${name}`)
        if (seen.has(name)) throw err(`error: line ${n}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: Number(t[1]), ranking: t.slice(2) })
    } else {
      throw err(`error: line ${n}: unknown directive ${word}`)
    }
  }
  if (candidates === null) throw err('error: no candidates')
  return { candidates, ballots }
}
"}

{"file_path":"src/count.js","content":"/** Runs the instant-runoff count. */
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0]))
    let active = 0
    let total = 0
    for (const b of ballots) {
      total += b.count
      const pick = b.ranking.find((c) => continuing.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const listing = [...votes].sort((a, b) => b[1] - a[1] || cmp(a[0], b[0]))
    const round = { listing, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0) return { rounds, winner: null }
    const top = listing.find(([, v]) => v * 2 > active)
    if (top) return { rounds, winner: top[0] }
    const min = Math.min(...votes.values())
    let tied = [...votes].filter(([, v]) => v === min).map(([c]) => c)
    const k = rounds.length
    for (let r = 0; r < k && tied.length > 1; ) {
      const m = Math.min(...tied.map((c) => history.get(c)[r]))
      const keep = tied.filter((c) => history.get(c)[r] === m)
      if (keep.length < tied.length) {
        tied = keep
        r = 0
      } else r++
    }
    tied.sort(cmp)
    const out = tied[tied.length - 1]
    continuing.delete(out)
    round.eliminated = out
  }
}
"}

