  const r = { userinfo: undefined, host: '', port: undefined }
  const at = a.lastIndexOf('@')
  let rest = a
  if (at >= 0) { r.userinfo = a.slice(0, at); rest = a.slice(at + 1) }
  const from = rest.lastIndexOf(']') + 1
  const c = rest.indexOf(':', from)
  if (c >= 0) { r.host = rest.slice(0, c); r.port = rest.slice(c + 1) } else r.host = rest
  return r
}

export function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
