  process.stderr.write(`error: line ${n}: ${msg}\n`)
  process.exit(2)
}
lines.forEach((line, i) => {
  const n = i + 1
  let target
  if (mode === 'normalize') target = parse(line)
  else {
    const sp = line.indexOf(' ')
    if (sp < 0) fail(n, 'expected a base and a reference')
    const base = parse(line.slice(0, sp))
    if (base.scheme === undefined) fail(n, 'the base has no scheme')
    target = resolve(base, parse(line.slice(sp + 1)))
  }
  const r = normalize(target)
  if (r.error) fail(n, `the ${r.error} has a truncated percent-encoding`)
  out.push(r.value)
})
if (out.length) process.stdout.write(out.join('\n') + '\n')
