  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = s[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
  }
  const advN = (k) => {
    for (let j = 0; j < k; j++) adv()
  }

  // consume a run of digits (per pred) with single underscores between digits; returns count
  const digitRun = (pred, from) => {
    let j = from
    if (!pred(s[j])) return j
    j++
    for (;;) {
      if (pred(s[j])) j++
      else if (s[j] === '_' && pred(s[j + 1])) j += 2
      else break
    }
    return j
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') adv()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      const sl = line
      const sc = col
      let depth = 0
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') {
          depth++
          advN(2)
        } else if (s[i] === '*' && s[i + 1] === '/') {
          depth--
          advN(2)
