  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    depLines.push(w.slice(1))
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
const deps = new Map()
for (const k of cost.keys()) deps.set(k, new Set())
for (const d of depLines) for (const x of d) if (!cost.has(x)) fail(`error: unknown task ${x}`)
for (const [a, ...rest] of depLines) for (const b of rest) deps.get(a).add(b)

const names = [...cost.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
const sdeps = new Map(names.map((k) => [k, [...deps.get(k)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of sdeps.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0n
  let d = 0
  for (const v of sdeps.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
}
for (const k of names) calc(k)
let total = 0n
for (const f of finish.values()) if (f > total) total = f

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ??= []).push(k)
  ws.forEach((w, i) => { out += `wave ${i}: ${w.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let best = 0n
    for (const v of names) if (sdeps.get(v).includes(u)) { const p = pr(v); if (p > best) best = p }
    prio.set(u, best + cost.get(u))
    return prio.get(u)
  }
  for (const k of names) pr(k)
  const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : a < b ? -1 : 1))
  const freeAt = Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const fin = new Map()
  let remaining = order.slice()
  let t = 0n
  let makespan = 0n
  while (remaining.length) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const idx = remaining.findIndex((u) => sdeps.get(u).every((d) => fin.has(d) && fin.get(d) <= t))
      if (idx < 0) break
      const u = remaining.splice(idx, 1)[0]
      const f = t + cost.get(u)
      fin.set(u, f)
      freeAt[wi] = f
      ran[wi].push(`${u}@${t}-${f}`)
      if (f > makespan) makespan = f
    }
    if (!remaining.length) break
    // next instant: a worker frees up or a running task finishes
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  ran.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
