          fail()
        }
      }
      return { k: 'call', name: up, args }
    }
    if (up === 'TRUE') return { k: 'bool', v: true }
    if (up === 'FALSE') return { k: 'bool', v: false }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') fail()
      const u2 = toks[p++].v.toUpperCase()
      if (u2 === 'TRUE' || u2 === 'FALSE' || (isOp('('))) fail()
      return { k: 'range', a: parseAddr(up), b: parseAddr(u2) }
    }
    return { k: 'ref', a: parseAddr(up) }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch { return null }
}

// range misplaced?
function misplaced(n, direct) {
  switch (n.k) {
    case 'range': return !direct
    case 'bin': return misplaced(n.l, false) || misplaced(n.r, false)
    case 'un': case 'paren': return misplaced(n.e, false)
    case 'call': return n.args.some((a) => misplaced(a, true))
    default: return false
  }
}

function rangeCells(a, b) {
  const out = []
  const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push([c, r])
  return out
}

function collectDeps(n, set) {
  switch (n.k) {
    case 'ref': if (n.a) set.set(key(n.a.col, n.a.row), n.a); break
    case 'range':
      if (n.a && n.b) for (const [c, r] of rangeCells(n.a, n.b)) set.set(key(c, r), { col: c, row: r })
      break
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
    case 'un': case 'paren': collectDeps(n.e, set); break
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
  }
}

