const state = new Map() // key -> value | 'busy'
function cellValue(col, row) {
  const k = key(col, row)
  const c = cells.get(k)
  if (!c) return num(0)
  if (state.has(k)) {
    const s = state.get(k)
    return s === 'busy' ? err('#CYCLE!') : s
  }
  state.set(k, 'busy')
  let v
  const t = c.content
  if (t[0] === '=') {
    const tree = parseFormula(t.slice(1))
    v = tree && !misplaced(tree, false) ? evalNode(tree) : err('#ERR!')
  } else v = literal(t)
