  }
  return [evalNode(n)]
}

function evalNode(n) {
  switch (n.k) {
    case 'num': return num(n.v)
    case 'bool': return bool(n.v)
    case 'paren': return evalNode(n.e)
    case 'ref': return n.a ? cellValue(n.a.col, n.a.row) : err('#REF!')
    case 'range': return err('#ERR!')
    case 'un': {
      const v = evalNode(n.e)
      if (v.t === 'e') return v
      const x = toNum(v)
      if (x.t === 'e') return x
      return num(n.op === '-' ? -x.v : x.v)
    }
    case 'bin': {
      const l = evalNode(n.l), r = evalNode(n.r)
      if (l.t === 'e') return l
      if (r.t === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        switch (n.op) {
          case '=': return bool(d === 0)
          case '<>': return bool(d !== 0)
          case '<': return bool(d < 0)
          case '<=': return bool(d <= 0)
          case '>': return bool(d > 0)
          default: return bool(d >= 0)
        }
      }
      const a = toNum(l), b = toNum(r)
      if (a.t === 'e') return a
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return evalCall(n)
  }
