    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
    case 'MIN': return num(Math.min(...nums))
    default: return num(Math.max(...nums))
  }
}

function show(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const out = []
for (const c of sorted) {
  const a = addrStr(c.col, c.row)
  if (mode === 'values') {
    out.push(`${a}=${show(cellValue(c.col, c.row))}`)
  } else {
    let line = a + ':'
    if (c.content[0] === '=') {
      const tree = parseFormula(c.content.slice(1))
      if (tree) {
        const set = new Map()
        collectDeps(tree, set)
        const ds = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
        for (const d of ds) line += ' ' + addrStr(d.col, d.row)
      }
    }
    out.push(line)
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
