function changes(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) { flush(); i++; j++; bs = i; ss = j }
    else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

export function merge(mode, mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ].sort((a, b) => a.bs - b.bs || a.side - b.side)
  const out = []
  let conflict = false
  const stable = (a, b) => {
    if (b > a) { if (mode === 'regions') out.push(`stable ${b - a}`); else out.push(...base.slice(a, b)) }
  }
  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) { re = Math.max(re, all[k].be); group.push(all[k++]) }
    stable(pos, rs)
    pos = re
    const baseL = base.slice(rs, re)
    const sides = [mine, theirs]
    const rep = [baseL, baseL]
    const touched = [false, false]
    for (const s of [0, 1]) {
      const g = group.filter(c => c.side === s)
      if (!g.length) continue
      touched[s] = true
      const minBs = Math.min(...g.map(c => c.bs)), maxBe = Math.max(...g.map(c => c.be))
      const first = g.reduce((a, c) => (c.ss < a ? c.ss : a), Infinity)
      const last = g.reduce((a, c) => (c.se > a ? c.se : a), -Infinity)
      rep[s] = sides[s].slice(first - (minBs - rs), last + (re - maxBe))
    }
    const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])
    const [m, t] = rep
    let res, label
    if (eq(m, t)) { res = m; label = touched[0] && touched[1] ? 'both' : touched[0] ? 'mine' : 'theirs' }
    else if (eq(m, baseL)) { res = t; label = 'theirs' }
    else if (eq(t, baseL)) { res = m; label = 'mine' }
    else {
      conflict = true
      if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseL.length} theirs=${t.length}`)
      else {
        out.push('<<<<<<< mine', ...m)
        if (mode === 'merge') out.push('||||||| base', ...baseL)
        out.push('=======', ...t, '>>>>>>> theirs')
      }
      continue
    }
    if (mode === 'regions') out.push(`${label} ${res.length}`)
    else out.push(...res)
  }
  stable(pos, base.length)
  return { out, conflict }
