const NAME = /^[A-Za-z0-9_.\/:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function fail(n, reason) {
  const e = new Error(reason)
  e.limiterMessage = `error: line ${n}: ${reason}`
  throw e
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  let started = false
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const d = t[0]
    const num = (field, v, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) fail(n, `${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    if (d === 'bucket' || d === 'window') {
      const want = d === 'bucket' ? 5 : 4
      if (t.length !== want) {
        fail(n, d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      }
      if (started) fail(n, 'declarations must come before the first event')
      if (!NAME.test(t[1])) fail(n, `invalid policy name ${t[1]}`)
      let p
      if (d === 'bucket') {
        const capacity = num('capacity', t[2], 1)
        const refill = num('refill', t[3], 0)
        const per = num('per', t[4], 1)
        p = { kind: 'bucket', name: t[1], capacity, refill, per }
      } else {
        const limit = num('limit', t[2], 0)
        const span = num('span', t[3], 1)
        p = { kind: 'window', name: t[1], limit, span }
      }
      if (policies.has(t[1])) fail(n, `policy ${t[1]} is declared twice`)
      policies.set(t[1], p)
    } else if (d === 'route') {
      if (t.length < 3) fail(n, 'expected route <prefix> <policy>...')
      if (started) fail(n, 'declarations must come before the first event')
