  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  const key = addrName(a)
  if (cells.has(key)) fail(`error: line ${i + 1}: cell ${key} is declared twice`)
  cells.set(key, { addr: a, content })
})

const sorted = [...cells.values()].sort((x, y) => x.addr.col - y.addr.col || x.addr.row - y.addr.row)
const out = []
if (mode === 'values') {
  const sheet = new Sheet(cells)
  for (const c of sorted) out.push(`${addrName(c.addr)}=${sheet.format(sheet.valueOf(addrName(c.addr)))}`)
} else {
  for (const c of sorted) {
    let names = []
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) {
        const set = new Map()
        const add = (a) => set.set(addrName(a), a)
        const walk = (n) => {
          if (n.k === 'ref') {
            if (n.addr) add(n.addr)
          } else if (n.k === 'range') {
            if (n.from && n.to) {
              const c1 = Math.min(n.from.col, n.to.col), c2 = Math.max(n.from.col, n.to.col)
              const r1 = Math.min(n.from.row, n.to.row), r2 = Math.max(n.from.row, n.to.row)
              for (let cc = c1; cc <= c2; cc++) for (let r = r1; r <= r2; r++) add({ col: cc, row: r })
            }
          } else if (n.k === 'call') n.args.forEach(walk)
          else if (n.k === 'bin') { walk(n.l); walk(n.r) }
          else if (n.k === 'un' || n.k === 'paren') walk(n.e)
        }
        walk(ast)
        names = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row).map(addrName)
      }
    }
    out.push(`${addrName(c.addr)}:` + names.map((n) => ' ' + n).join(''))
  }
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

