{"file_path":"src/merge.js","content":"function changes(base, side) {
  const n = base.length
  const m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const out = []
  let i = 0
  let j = 0
  let bs = 0
  let ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++
      j++
      bs = i
      ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n
  j = m
  flush()
  return out
}

const same = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs) {
  const all = [
    ...changes(base, mine).map(c => ({ ...c, side: 0 })),
    ...changes(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)
  const docs = [mine, theirs]
  const result = []
  let pos = 0
  let k = 0
  while (k < all.length) {
    const group = [all[k++]]
    let end = group[0].be
    while (k < all.length && all[k].bs <= end) {
      group.push(all[k])
      end = Math.max(end, all[k].be)
      k++
    }
    const start = group[0].bs
    if (start > pos) result.push({ kind: 'stable', lines: base.slice(pos, start) })
    pos = end
    const baseLines = base.slice(start, end)
    const repl = [baseLines, baseLines]
    for (const s of [0, 1]) {
      const cs = group.filter(c => c.side === s)
      if (!cs.length) continue
      const lo = Math.min(...cs.map(c => c.bs))
      const hi = Math.max(...cs.map(c => c.be))
      const first = cs.reduce((a, c) => (c.bs < a.bs ? c : a))
      const last = cs.reduce((a, c) => (c.be > a.be ? c : a))
      repl[s] = docs[s].slice(first.ss - (lo - start), last.se + (end - hi))
    }
    const [m, t] = repl
    if (same(m, t)) result.push({ kind: 'both', lines: m })
    else if (same(m, baseLines)) result.push({ kind: 'theirs', lines: t })
    else if (same(t, baseLines)) result.push({ kind: 'mine', lines: m })
    else result.push({ kind: 'conflict', mine: m, base: baseLines, theirs: t })
  }
  if (pos < base.length) result.push({ kind: 'stable', lines: base.slice(pos) })
  return result
}
"}

